#include <vector>
#include <string>
#include <algorithm>
#define main original_main
#include "study_native_source.cuh"
#undef main
#include "study_expected.h"
static void ck(cudaError_t e){if(e!=cudaSuccess){fprintf(stderr,"%s\n",cudaGetErrorString(e));exit(2);}}
struct Case {float *v,*g,*lambda,*rates,delta;int *m;int index;};
static void run(Case &c,bool greek){if(greek)Pathcalc_Portfolio_KernelGPU<<<4,64>>>(c.v,c.g,c.lambda,c.m,c.rates,c.delta,40,80,15);else Pathcalc_Portfolio_KernelGPU2<<<4,64>>>(c.v,c.lambda,c.m,c.rates,c.delta,40,80,15);}
static double trial(Case &c,int repeats,std::vector<float>&output,double &err){double total=0.;for(bool greek:{false,true}){ck(cudaDeviceSynchronize());auto t=std::chrono::steady_clock::now();for(int i=0;i<repeats;++i)run(c,greek);ck(cudaDeviceSynchronize());total+=std::chrono::duration<double>(std::chrono::steady_clock::now()-t).count()/repeats;std::vector<float>v(NPATH),g(NPATH);ck(cudaMemcpy(v.data(),c.v,NPATH*sizeof(float),cudaMemcpyDeviceToHost));output.insert(output.end(),v.begin(),v.end());for(float x:v)err=std::max(err,std::abs(double(x)-EXPECTED_V[c.index]));if(greek){ck(cudaMemcpy(g.data(),c.g,NPATH*sizeof(float),cudaMemcpyDeviceToHost));output.insert(output.end(),g.begin(),g.end());for(float x:g)err=std::max(err,std::abs(double(x)-EXPECTED_G[c.index]));}}return total;}
int main(){int m[15]={4,4,4,8,8,8,20,20,20,28,28,28,40,40,40};float rates[15]={.045f,.05f,.055f,.045f,.05f,.055f,.045f,.05f,.055f,.045f,.05f,.055f,.045f,.05f,.055f};float ds[3]={.25f,.125f,.375f},ls[3]={.2f,.15f,.25f};std::vector<Case>cases;std::vector<float>prefix;for(int k=0;k<3;++k){Case c;c.index=k;c.delta=ds[k];std::vector<float>lambda(80,ls[k]);prefix.insert(prefix.end(),lambda.begin(),lambda.end());for(int x:m)prefix.push_back(float(x));prefix.insert(prefix.end(),rates,rates+15);prefix.push_back(c.delta);ck(cudaMalloc(&c.v,NPATH*sizeof(float)));ck(cudaMalloc(&c.g,NPATH*sizeof(float)));ck(cudaMalloc(&c.lambda,80*sizeof(float)));ck(cudaMalloc(&c.rates,15*sizeof(float)));ck(cudaMalloc(&c.m,15*sizeof(int)));ck(cudaMemcpy(c.lambda,lambda.data(),80*sizeof(float),cudaMemcpyHostToDevice));ck(cudaMemcpy(c.rates,rates,sizeof(rates),cudaMemcpyHostToDevice));ck(cudaMemcpy(c.m,m,sizeof(m),cudaMemcpyHostToDevice));cases.push_back(c);}for(auto &c:cases){std::vector<float>unused;double e=0.;trial(c,1,unused,e);}for(int tr=1;tr<=5;++tr){std::vector<float>out=prefix;double elapsed=0.,err=0.;for(auto &c:cases)elapsed+=trial(c,3,out,err);bool ok=out.size()==2646&&err<=1e-3;for(float x:out)ok&=std::isfinite(x);std::string path="trial_"+std::to_string(tr)+".bin";FILE*f=fopen(path.c_str(),"wb");fwrite(out.data(),sizeof(float),out.size(),f);fclose(f);printf("STUDY_TRIAL {\"trial\":%d,\"time_seconds\":%.17g,\"correct\":%s,\"checked_values\":2646,\"max_abs_error\":%.17g,\"timing_region\":\"sum_three_cases_value_and_greek_kernel_means\",\"jit_excluded\":true,\"internal_repeats\":3,\"output_artifact\":{\"path\":\"%s\",\"dtype\":\"float32\",\"count\":2646,\"byte_order\":\"little\"}}\n",tr,elapsed,ok?"true":"false",err,path.c_str());if(!ok)return 3;}for(auto &c:cases){cudaFree(c.v);cudaFree(c.g);cudaFree(c.lambda);cudaFree(c.rates);cudaFree(c.m);}return 0;}
